create table public.leaderboard_rules(id text primary key,description text not null,ordering text[] not null,minimum_matches int not null default 1,updated_at timestamptz not null default now());insert into public.leaderboard_rules(id,description,ordering)values('elo-v1','Ranked results only. Elo v1 uses K=32 and arithmetic-mean doubles teams.',array['rating desc','wins desc','win_rate desc','losses asc','last_match_at desc','player_id asc'])on conflict(id)do nothing;
create view public.public_leaderboards as select le.scope,le.club_id,c.slug club_slug,le.player_id,p.public_slug,p.display_name,le.rating,le.wins,le.losses,le.win_rate,le.current_streak,le.longest_win_streak,le.last_match_at,le.calculation_version,row_number()over(partition by le.scope,le.club_id order by le.rating desc,le.wins desc,le.win_rate desc,le.losses asc,le.last_match_at desc nulls last,le.player_id asc)::bigint rank from public.leaderboard_entries le join public.players p on p.id=le.player_id and p.visibility='public'and p.merged_into_player_id is null left join public.clubs c on c.id=le.club_id where le.wins+le.losses>=1;
create index leaderboard_calculation_version_idx on public.leaderboard_entries(calculation_version desc);grant select on public.public_leaderboards,public.leaderboard_rules to anon,authenticated;revoke insert,update,delete on public.leaderboard_rules from anon,authenticated;
